css_tokens_index_css.keyframes:
@keyframes flame-pulse {
  0%, 100% { transform: scale(1) rotate(-1deg); filter: drop-shadow(0 0 16px rgba(245,158,11,0.6)); }
  50% { transform: scale(1.08) rotate(2deg); filter: drop-shadow(0 0 26px rgba(234,88,12,0.85)); }
}
@keyframes subtle-float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-4px); }
}

css_tokens_index_css.utility_classes:
.animate-flame-pulse {
  animation: flame-pulse 2.2s ease-in-out infinite;
}
.animate-float {
  animation: subtle-float 3.5s ease-in-out infinite;
}
